        // Pro jednoduchost: Test nanečisto aktualizuje "zásobník chyb" pouze těmi novými.
        // Chceme-li být přísní:
        const uniqueMistakes = Array.from(new Set([...currentMistakes, ...result.mistakes]));
        setMistakes(uniqueMistakes); // Přidáme nové chyby k existujícím

        setLastTestQuestions(result.questionsUsed);
        setLastUserAnswers(result.userAnswers);
    } else if (mode === AppMode.MISTAKES) {
        // Pokud opravuje chyby a odpoví správně, chyba zmizí.
        // V režimu MISTAKES vrací TestRunner v result.mistakes ty, které ZNOVU spletl.
        // Takže ty, které spletl znovu, zůstávají. Ty co dal dobře, zmizí.
        // Ale pozor: TestRunner vrací v result.mistakes ID otázek, které v TOMTO běhu spletl.
        // Musíme zachovat ty, které se v tomto běhu netestovaly (pokud bychom netestovali všechny chyby naráz).
        // V naší implementaci TestRunner bere VŠECHNY chyby. Takže result.mistakes jsou zbývající chyby.
        setMistakes(result.mistakes);
    }

    setMode(AppMode.MENU);
  };

  const closeBrowser = () => {
      setMode(AppMode.MENU);
      setBrowserSearch("");
      setExpandedQuestionId(null);
  };

  const handleLogout = () => {
      setCurrentUser(null);
      setSubject(null);
      setMode(AppMode.MENU);
      setLastResult(null);
      setMistakesSPS([]);
      setMistakesSTT([]);
