        const savedSPS = localStorage.getItem(`mistakes_SPS_${currentUser.username}`);
        const savedSTT = localStorage.getItem(`mistakes_STT_${currentUser.username}`);

        if (savedSPS) setMistakesSPS(JSON.parse(savedSPS));
