import React, { useState } from 'react';
import { getUserDefinition, User } from '../users';

interface Props {
  onLogin: (user: User) => void;
}

export const LoginScreen: React.FC<Props> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  // State pro nastavování nového hesla
  const [isSettingNewPassword, setIsSettingNewPassword] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [tempUser, setTempUser] = useState<User | null>(null);

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const userDef = getUserDefinition(username);

    if (!userDef) {
      setError('Uživatel nenalezen');
      return;
    }

    // 1. Zkusíme najít uložené vlastní heslo v prohlížeči
    const storedCustomPassword = localStorage.getItem(`auth_pass_${userDef.username}`);

    if (storedCustomPassword) {
        // Pokud má uživatel nastavené vlastní heslo
        if (password === storedCustomPassword) {
            // Heslo sedí -> Přihlásit
            onLogin(userDef);
            return;
        } else if (password === userDef.accessCode) {
            // Heslo nesedí, ALE zadal "Startovací/Resetovací kód" z users.ts
            // Pustíme ho dál, ale musí si nastavit nové heslo (Reset)
            setTempUser(userDef);
            setIsSettingNewPassword(true);
            setError('');
            return;
        } else {
            setError('Nesprávné heslo');
            return;
        }
    } else {
        // Uživatel ještě nemá vlastní heslo (první přihlášení)
        if (password === userDef.accessCode) {
            // Zadal správný startovací kód -> Musí si nastavit heslo
            setTempUser(userDef);
            setIsSettingNewPassword(true);
            setError('');
        } else {
            setError('Nesprávný startovací kód');
        }
    }
  };

  const handleSetPasswordSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (newPassword.length < 3) {
          setError('Heslo musí mít alespoň 3 znaky');
          return;
      }
      if (newPassword !== confirmPassword) {
          setError('Hesla se neshodují');
          return;
      }

      if (tempUser) {
          // Uložíme nové heslo do localStorage
          localStorage.setItem(`auth_pass_${tempUser.username}`, newPassword);
          // Přihlásíme uživatele
          onLogin(tempUser);
      }
  };

  if (isSettingNewPassword) {
      return (
        <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
            <div className="bg-white p-8 rounded-2xl shadow-xl max-w-sm w-full border border-gray-100">
                <div className="text-center mb-6">
                    <h2 className="text-xl font-bold text-gray-900">Nastavení nového hesla</h2>
                    <p className="text-gray-500 text-sm mt-2">Pro uživatele: <span className="font-bold">{tempUser?.username}</span></p>
                </div>
                <form onSubmit={handleSetPasswordSubmit} className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Nové heslo</label>
                        <input type="password" value={newPassword} onChange={e => setNewPassword(e.target.value)} className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Zadejte nové heslo" autoFocus />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Potvrzení hesla</label>
                        <input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Zadejte heslo znovu" />
                    </div>
                    {error && <div className="text-red-500 text-sm text-center bg-red-50 p-2 rounded-lg border border-red-100">{error}</div>}
                    <button type="submit" className="w-full bg-green-600 text-white font-bold py-3 rounded-lg hover:bg-green-700 transition-colors shadow-md">Uložit a přihlásit</button>
                </form>
            </div>
        </div>
      );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl max-w-sm w-full border border-gray-100">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-gray-900">Přihlášení</h1>
          <p className="text-gray-500 text-sm mt-2">Maturitní testy SPS a STT</p>
        </div>

        <form onSubmit={handleLoginSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Uživatelské jméno</label>
            <input
              type="text"
              value={username}
              onChange={(e) => {
                  setUsername(e.target.value);
                  setError('');
              }}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all"
              placeholder="Zadejte jméno"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Heslo</label>
            <input
              type="password"
              value={password}
              onChange={(e) => {
                  setPassword(e.target.value);
                  setError('');
              }}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all"
              placeholder="Zadejte heslo"
            />
          </div>

          {error && (
            <div className="text-red-500 text-sm text-center bg-red-50 p-2 rounded-lg border border-red-100">
              {error}
            </div>
          )}

          <button
            type="submit"
            className="w-full bg-blue-600 text-white font-bold py-3 rounded-lg hover:bg-blue-700 transition-colors shadow-md hover:shadow-lg"
          >
            Přihlásit se
          </button>

          <p className="text-xs text-center text-gray-400 mt-4">
              První přihlášení? Použijte startovací kód od učitele.
              <br/>Zapomněli jste heslo? Požádejte o kód znovu.
          </p>
        </form>
      </div>
    </div>
  );
};

