// Startovací heslo pro registraci (jak jsi chtěl "01")
export const REGISTRATION_CODE = "01";

import React, { useState } from 'react';
import { AppUser, REGISTRATION_CODE } from '../users';
import { auth } from '../firebaseConfig';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';

interface Props {
  onLogin: (user: AppUser) => void;
}

export const LoginScreen: React.FC<Props> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);

  const [name, setName] = useState(''); // Jméno (např. "Novák")
  const [password, setPassword] = useState('');
  const [teacherCode, setTeacherCode] = useState(''); // Kód "01"
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Firebase používá email, my chceme jen jméno. 
  // Finta: vytvoříme fake email: jmeno@maturita.cz
  const createFakeEmail = (username: string) => {
      // Odstraníme háčky čárky a mezery pro email
      const cleanName = username.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, '').toLowerCase();
      return `${cleanName}@maturita.app`;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!auth) {
        setError("Chyba: Firebase není připojen (chybí config).");
        setLoading(false);
        return;
    }

    try {
        const fakeEmail = createFakeEmail(name);

        if (isRegistering) {
            // REGISTRACE
            if (teacherCode !== REGISTRATION_CODE) {
                setError("Špatný kód od učitele!");
                setLoading(false);
                return;
            }
            if (password.length < 6) {
                setError("Heslo musí mít alespoň 6 znaků.");
                setLoading(false);
                return;
            }

            const userCredential = await createUserWithEmailAndPassword(auth, fakeEmail, password);
            // Uložíme jméno uživatele
            await updateProfile(userCredential.user, { displayName: name });

            onLogin({
                uid: userCredential.user.uid,
                email: fakeEmail,
                displayName: name
            });

        } else {
            // PŘIHLÁŠENÍ
            const userCredential = await signInWithEmailAndPassword(auth, fakeEmail, password);
            onLogin({
                uid: userCredential.user.uid,
                email: fakeEmail,
                displayName: userCredential.user.displayName || name
            });
        }

    } catch (err: any) {
        console.error(err);
        if (err.code === 'auth/invalid-credential' || err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password') {
            setError("Špatné jméno nebo heslo.");
        } else if (err.code === 'auth/email-already-in-use') {
            setError("Toto jméno je už zabrané. Zvolte jiné nebo se přihlašte.");
        } else if (err.code === 'auth/network-request-failed') {
            setError("Chyba připojení k internetu.");
        } else {
            setError("Chyba přihlášení: " + err.message);
        }
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl max-w-sm w-full border border-gray-100">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-gray-900">
              {isRegistering ? "Nová registrace" : "Přihlášení"}
          </h1>
          <p className="text-gray-500 text-sm mt-2">Maturitní testy SPS a STT</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
                {isRegistering ? "Zvolte si přihlašovací jméno" : "Vaše jméno"}
            </label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="např. Novak"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
                 {isRegistering ? "Zvolte si heslo (min. 6 znaků)" : "Vaše heslo"}
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="******"
              required
            />
          </div>

          {isRegistering && (
             <div className="bg-yellow-50 p-3 rounded-lg border border-yellow-100">
                <label className="block text-sm font-bold text-yellow-800 mb-1">Kód od učitele</label>
                <input
                type="text"
                value={teacherCode}
                onChange={(e) => setTeacherCode(e.target.value)}
                className="w-full p-2 border border-yellow-300 rounded focus:ring-2 focus:ring-yellow-500 outline-none text-center font-mono text-lg uppercase"
                placeholder="01"
                maxLength={2}
                required
                />
             </div>
          )}

          {error && (
            <div className="text-red-500 text-sm text-center bg-red-50 p-2 rounded-lg border border-red-100">
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full text-white font-bold py-3 rounded-lg transition-colors shadow-md ${isRegistering ? 'bg-green-600 hover:bg-green-700' : 'bg-blue-600 hover:bg-blue-700'} ${loading ? 'opacity-70 cursor-wait' : ''}`}
          >
            {loading ? "Pracuji..." : (isRegistering ? "Vytvořit účet" : "Přihlásit se")}
          </button>

          <div className="text-center mt-4">
              <button 
                type="button"
                onClick={() => {
                    setIsRegistering(!isRegistering);
                    setError('');
                    setTeacherCode('');
                }}
                className="text-sm text-blue-600 hover:text-blue-800 underline"
              >
                  {isRegistering ? "Už mám účet -> Přihlásit se" : "Jsem tu nový -> Zaregistrovat se"}
              </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { QUESTIONS_SPS, QUESTIONS_STT } from './constants';
import { AppMode, TestResult, Question, Subject } from './types';
import { TestRunner } from './components/TestRunner';
import { BrowserQuestionItem } from './components/BrowserQuestionItem';
import { LoginScreen } from './components/LoginScreen';
import { AppUser } from './users';
import { db, auth } from './firebaseConfig';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { onAuthStateChanged, signOut } from 'firebase/auth';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<AppUser | null>(null);
  const [loadingUser, setLoadingUser] = useState(true);

  const [subject, setSubject] = useState<Subject | null>(null);
  const [mode, setMode] = useState<AppMode>(AppMode.MENU);

  const [mistakesSPS, setMistakesSPS] = useState<number[]>([]);
  const [mistakesSTT, setMistakesSTT] = useState<number[]>([]);

  const [lastResult, setLastResult] = useState<TestResult | null>(null);
  const [browserSearch, setBrowserSearch] = useState("");
  const [expandedQuestionId, setExpandedQuestionId] = useState<number | null>(null);

  const [lastTestQuestions, setLastTestQuestions] = useState<Question[]>([]);
  const [lastUserAnswers, setLastUserAnswers] = useState<Record<number, number>>({});

  // 1. SLEDOVÁNÍ STAVU PŘIHLÁŠENÍ (Firebase Auth)
  useEffect(() => {
      if(!auth) {
          setLoadingUser(false);
          return;
      }

      const unsubscribe = onAuthStateChanged(auth, (user) => {
          if (user) {
              setCurrentUser({
                  uid: user.uid,
                  email: user.email || '',
                  displayName: user.displayName || 'Student'
              });
          } else {
              setCurrentUser(null);
          }
          setLoadingUser(false);
      });

      return () => unsubscribe();
  }, []);

  // 2. NAČTENÍ DAT Z DATABÁZE (Firestore)
  useEffect(() => {
    if (currentUser && db) {
        const userDocRef = doc(db, "users", currentUser.uid);

        // Posloucháme změny v reálném čase (kdyby se přihlásil na mobilu i PC)
        const unsubDoc = onSnapshot(userDocRef, (docSnap) => {
            if (docSnap.exists()) {
                const data = docSnap.data();
                setMistakesSPS(data.mistakesSPS || []);
                setMistakesSTT(data.mistakesSTT || []);
            } else {
                // Nový uživatel v DB - vytvoříme prázdný záznam
                setDoc(userDocRef, {
                    mistakesSPS: [],
                    mistakesSTT: [],
                    lastLogin: new Date().toISOString(),
                    displayName: currentUser.displayName
                }, { merge: true });
            }
        }, (error) => {
            console.error("Chyba při čtení dat:", error);
        });

        return () => unsubDoc();
    } else {
        setMistakesSPS([]);
        setMistakesSTT([]);
    }
  }, [currentUser]);

  const currentQuestions = useMemo(() => {
    if (subject === 'SPS') return QUESTIONS_SPS;
    if (subject === 'STT') return QUESTIONS_STT;
    return [];
  }, [subject]);

  const currentMistakes = subject === 'SPS' ? mistakesSPS : mistakesSTT;

  const setMistakes = async (newMistakes: number[]) => {
      // 1. Aktualizujeme lokální state pro okamžitou reakci UI
      if (subject === 'SPS') setMistakesSPS(newMistakes);
      else if (subject === 'STT') setMistakesSTT(newMistakes);

      // 2. Uložíme do Firestore
      if (currentUser && db) {
          try {
              const userDocRef = doc(db, "users", currentUser.uid);
              const updateData = subject === 'SPS' 
                ? { mistakesSPS: newMistakes } 
                : { mistakesSTT: newMistakes };

              await setDoc(userDocRef, updateData, { merge: true });
          } catch (e) {
              console.error("Nepodařilo se uložit chyby:", e);
              alert("Pozor: Jste offline, chyby se neuložily do cloudu.");
          }
      }
  };

  const handleTestComplete = (result: TestResult) => {
    setLastResult(result);

    if (mode === AppMode.MOCK_TEST) {
        // V testu nanečisto přidáváme nové chyby k těm starým (sjednocení)
        const uniqueMistakes = Array.from(new Set([...currentMistakes, ...result.mistakes]));
        setMistakes(uniqueMistakes);

        setLastTestQuestions(result.questionsUsed);
        setLastUserAnswers(result.userAnswers);
    } else if (mode === AppMode.MISTAKES) {
        // V režimu opravy chyb: nahradíme seznam chyb jen těmi, které udělal znovu
        setMistakes(result.mistakes);
    }

    setMode(AppMode.MENU);
  };

  const closeBrowser = () => {
      setMode(AppMode.MENU);
      setBrowserSearch("");
      setExpandedQuestionId(null);
  };

  const handleLogout = () => {
      if(auth) signOut(auth);
      setSubject(null);
      setMode(AppMode.MENU);
      setLastResult(null);
  };

  const getMenuButtonClass = (color: string) => 
    `w-full p-6 rounded-xl shadow-md transition-all duration-300 transform hover:-translate-y-1 hover:shadow-xl flex flex-col items-center justify-center gap-3 text-center border border-gray-100 ${color}`;

  const renderBrowser = () => {
      const filtered = currentQuestions.filter(q => 
          q.text.toLowerCase().includes(browserSearch.toLowerCase()) || 
          q.id.toString().includes(browserSearch)
      );

      return (
          <div className="max-w-4xl mx-auto w-full p-4">
               <div className="bg-white sticky top-0 z-10 shadow-sm border-b border-gray-200 px-6 py-4 mb-6 flex justify-between items-center rounded-b-xl gap-4">
                  <button onClick={closeBrowser} className="text-gray-500 hover:text-gray-900 transition-colors">
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                  </button>
                  <div className="flex-1 relative">
                      <input 
                          type="text" 
                          value={browserSearch}
                          onChange={(e) => setBrowserSearch(e.target.value)}
                          placeholder="Hledat otázku (text nebo číslo)..."
                          className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                      />
                       <svg className="w-5 h-5 text-gray-400 absolute left-3 top-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                  </div>
              </div>

              <div className="space-y-4">
                  {filtered.length === 0 ? (
                      <div className="text-center py-12 text-gray-500">
                          Nebyly nalezeny žádné otázky odpovídající hledání.
                      </div>
                  ) : (
                      filtered.map(q => (
                          <BrowserQuestionItem 
                              key={q.id} 
                              question={q} 
                              isExpanded={expandedQuestionId === q.id}
                              onToggle={() => setExpandedQuestionId(expandedQuestionId === q.id ? null : q.id)}
                          />
                      ))
                  )}
              </div>
          </div>
      );
  };

  // ----------------------------------------------------------------------
  // RENDER LOGIC
  // ----------------------------------------------------------------------

  if (loadingUser) {
      return <div className="min-h-screen flex items-center justify-center text-gray-500">Načítám...</div>;
  }

  if (!currentUser) {
      return <LoginScreen onLogin={(user) => setCurrentUser(user)} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 text-gray-900 font-sans relative">
      {/* Watermark proti sdílení */}
      <div className="fixed bottom-2 right-4 text-[10px] text-gray-300 pointer-events-none z-[100] select-none">
          User: {currentUser.displayName}
      </div>

      {lastResult && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl p-8 max-w-md w-full shadow-2xl animate-in fade-in zoom-in duration-300">
                <div className="text-center">
                    <div className={`mx-auto w-20 h-20 rounded-full flex items-center justify-center mb-4 ${lastResult.passed ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                        {lastResult.passed ? (
                            <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                        ) : (
                            <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                        )}
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-1">{lastResult.passed ? "Prošel(a) jsi!" : "Neprošel(a) jsi"}</h2>
                    <p className="text-gray-500 mb-6">
