    try {
        let jsonStr = input.trim();

        // 1. Odstranění "const firebaseConfig =" a středníků, pokud tam jsou
        if (jsonStr.includes("=")) {
            jsonStr = jsonStr.substring(jsonStr.indexOf("=") + 1).trim();
        }
        if (jsonStr.endsWith(";")) {
            jsonStr = jsonStr.slice(0, -1).trim();
        }

        // 2. Pokus o opravu JS objektu na JSON (přidání uvozovek klíčům)
        // Nahradí klíč: "hodnota" za "klíč": "hodnota"
        // (Jednoduchý regex pro běžný formát Firebase configu)
        jsonStr = jsonStr.replace(/([{,]\s*)([a-zA-Z0-9_]+)(\s*:)/g, '$1"$2"$3');

        // 3. Nahrazení jednoduchých uvozovek za dvojité
        jsonStr = jsonStr.replace(/'/g, '"');

        // Test parsování
        const parsed = JSON.parse(jsonStr);

        // Validace základních polí
        if (!parsed.apiKey || !parsed.authDomain) {
            throw new Error("Chybí klíčové údaje (apiKey, authDomain).");
        }

        localStorage.setItem("FIREBASE_CONFIG", JSON.stringify(parsed));
        window.location.reload();
        return true;
    } catch (e: any) {
        alert("Nepodařilo se zpracovat konfiguraci. Ujistěte se, že kopírujete správný objekt. \n\nChyba: " + e.message);
        return false;
    }
};

export const resetFirebaseConfig = () => {
    localStorage.removeItem("FIREBASE_CONFIG");
    window.location.reload();
};

import React, { useState } from 'react';
import { AppUser, REGISTRATION_CODE } from '../users';
import { auth } from '../firebaseConfig';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { saveFirebaseConfig } from '../firebaseConfig';

interface Props {
  onLogin: (user: AppUser) => void;
}

export const LoginScreen: React.FC<Props> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);

  const [name, setName] = useState(''); 
  const [password, setPassword] = useState('');
  const [regCode, setRegCode] = useState(''); 
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Stav pro konfigurační modální okno
  const [showConfig, setShowConfig] = useState(false);
  const [configInput, setConfigInput] = useState('');

  const createFakeEmail = (username: string) => {
      const cleanName = username.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, '').toLowerCase();
      return `${cleanName}@maturita.app`;
  };

  const handleGuestLogin = () => {
      onLogin({
          uid: 'guest',
          email: 'guest@maturita.app',
          displayName: 'Host (Offline)'
      });
  };

  const handleSaveConfig = () => {
      if (!configInput.trim()) return;
      saveFirebaseConfig(configInput);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!auth) {
        setError("Chyba: Firebase není připojen. Zkuste 'Pokračovat jako Host'.");
        setLoading(false);
        return;
    }

    try {
        const fakeEmail = createFakeEmail(name);

        if (isRegistering) {
            if (regCode !== REGISTRATION_CODE) {
                setError("Neplatný registrační kód.");
                setLoading(false);
                return;
            }
            if (password.length < 6) {
                setError("Heslo musí mít alespoň 6 znaků.");
                setLoading(false);
                return;
            }

            const userCredential = await createUserWithEmailAndPassword(auth, fakeEmail, password);
            await updateProfile(userCredential.user, { displayName: name });

            onLogin({
                uid: userCredential.user.uid,
                email: fakeEmail,
                displayName: name
            });

        } else {
            const userCredential = await signInWithEmailAndPassword(auth, fakeEmail, password);
            onLogin({
                uid: userCredential.user.uid,
                email: fakeEmail,
                displayName: userCredential.user.displayName || name
            });
        }

    } catch (err: any) {
        console.error(err);
        // Specifická detekce chyby API klíče
        if (err.code === 'auth/invalid-api-key' || err.message.includes('api-key-not-valid') || err.code === 'auth/api-key-not-valid') {
            setError("Neplatný API klíč databáze. Aplikace není správně propojena s Firebase.");
        } else if (err.code === 'auth/invalid-credential' || err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password') {
            setError("Špatné jméno nebo heslo.");
        } else if (err.code === 'auth/email-already-in-use') {
            setError("Toto jméno je už zabrané. Zvolte jiné.");
        } else if (err.code === 'auth/network-request-failed') {
            setError("Chyba připojení k internetu.");
        } else {
            setError("Chyba: " + err.message);
        }
    } finally {
        setLoading(false);
    }
  };

