import React, { useState } from 'react';
import { AppUser } from '../users';
import { auth } from '../firebaseConfig';
import { signInWithEmailAndPassword } from 'firebase/auth';

interface Props {
  onLogin: (user: AppUser) => void;
}

export const LoginScreen: React.FC<Props> = ({ onLogin }) => {
  const [name, setName] = useState(''); 
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const createFakeEmail = (username: string) => {
      // 1. Převedeme na malá písmena a odstraníme mezery na začátku/konci
      let cleanName = username.trim().toLowerCase();

      // 2. Pokud uživatel zadal celý email (např. pepa@maturita.app),
      // odstraníme tu koncovku, abychom ji tam nepřidali dvakrát.
      // Tím zajistíme, že funguje vstup "pepa" i "pepa@maturita.app"
      cleanName = cleanName.replace('@maturita.app', '');

      // 3. Odstraníme diakritiku a mezery uvnitř jména
      cleanName = cleanName.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, '');

      // 4. Vrátíme správný formát
      return `${cleanName}@maturita.app`;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!auth) {
        setError("Chyba: Firebase není nakonfigurován.");
        setLoading(false);
        return;
    }

    try {
        const fakeEmail = createFakeEmail(name);
        console.log("Pokus o přihlášení:", fakeEmail);

        // Logika přihlášení
        const userCredential = await signInWithEmailAndPassword(auth, fakeEmail, password);
        onLogin({
            uid: userCredential.user.uid,
            email: fakeEmail,
            displayName: userCredential.user.displayName || name
        });

    } catch (err: any) {
        console.error("Login Error:", err);

        let msg = "Nastala neznámá chyba.";
        const code = err.code;
        const message = err.message || "";

        if (code === 'auth/invalid-credential' || code === 'auth/wrong-password') {
            // Tento kód může znamenat špatné heslo NEBO neexistujícího uživatele (zabezpečení proti hádání emailů)
            msg = "Nesprávné uživatelské jméno nebo heslo.";
        } else if (code === 'auth/user-not-found' || code === 'auth/invalid-email') {
            msg = "Tento uživatel neexistuje. Požádejte učitele o vytvoření účtu.";
        } else if (code === 'auth/too-many-requests') {
            msg = "Příliš mnoho nezdařených pokusů. Zkuste to prosím později.";
        } else if (code === 'auth/network-request-failed') {
            msg = "Chyba připojení k internetu. Jste online?";
        } else if (
            code === 'auth/api-key-not-valid' || 
            code === 'auth/invalid-api-key' || 
            message.includes('api-key-not-valid')
        ) {
            msg = "CHYBA KONFIGURACE: Špatný API klíč ve firebaseConfig.ts.";
        } else {
            msg = "Chyba: " + message;
        }

        setError(msg);
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl max-w-sm w-full border border-gray-100">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1" />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-gray-900">
              Přihlášení
          </h1>
          <p className="text-gray-500 text-sm mt-2">Maturitní testy SPS a STT</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
                Uživatelské jméno
            </label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="např. Novak"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
                 Heslo
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="******"
            />
          </div>

          {error && (
            <div className="text-red-500 text-sm text-center bg-red-50 p-3 rounded-lg border border-red-100">
              <p>{error}</p>
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full text-white font-bold py-3 rounded-lg transition-colors shadow-md bg-blue-600 hover:bg-blue-700 ${loading ? 'opacity-70 cursor-wait' : ''}`}
          >
            {loading ? "Ověřuji..." : "Přihlásit se"}
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { AppUser, REGISTRATION_CODE } from '../users';
import { auth } from '../firebaseConfig';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';

interface Props {
  onLogin: (user: AppUser) => void;
}

export const LoginScreen: React.FC<Props> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [name, setName] = useState(''); 
  const [password, setPassword] = useState('');
  const [regCode, setRegCode] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const createFakeEmail = (username: string) => {
      let cleanName = username.trim().toLowerCase();
      cleanName = cleanName.replace('@maturita.app', '');
      cleanName = cleanName.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, '');
      return `${cleanName}@maturita.app`;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!auth) {
        setError("Chyba: Firebase není nakonfigurován.");
        setLoading(false);
        return;
    }

    try {
        const fakeEmail = createFakeEmail(name);

        if (isRegistering) {
            // REGISTRACE
            if (regCode !== REGISTRATION_CODE) {
                throw new Error("Nesprávný kód školy.");
            }
            if (password.length < 6) {
                throw new Error("Heslo musí mít alespoň 6 znaků.");
            }

            const userCredential = await createUserWithEmailAndPassword(auth, fakeEmail, password);

            // Uložíme jméno (displayName) do profilu
            await updateProfile(userCredential.user, { displayName: name });

            onLogin({
                uid: userCredential.user.uid,
                email: fakeEmail,
                displayName: name
            });

        } else {
            // PŘIHLÁŠENÍ
            const userCredential = await signInWithEmailAndPassword(auth, fakeEmail, password);
            onLogin({
                uid: userCredential.user.uid,
                email: fakeEmail,
                displayName: userCredential.user.displayName || name
            });
        }

    } catch (err: any) {
        console.error("Auth Error:", err);

        let msg = "Nastala neznámá chyba.";
        const code = err.code;
        const message = err.message || "";

        if (message === "Nesprávný kód školy.") {
            msg = message;
        } else if (message.includes("Heslo musí mít alespoň 6 znaků")) {
             msg = message;
        } else if (code === 'auth/invalid-credential' || code === 'auth/wrong-password') {
            msg = isRegistering ? "Chyba při registraci." : "Nesprávné jméno nebo heslo. Pokud nemáte účet, přepněte na Registraci.";
        } else if (code === 'auth/user-not-found' || code === 'auth/invalid-email') {
            msg = "Uživatel neexistuje. Zaregistrujte se.";
        } else if (code === 'auth/email-already-in-use') {
            msg = "Toto jméno je již obsazené. Přihlašte se.";
        } else if (code === 'auth/weak-password') {
            msg = "Heslo je příliš slabé (min. 6 znaků).";
        } else if (code === 'auth/network-request-failed') {
            msg = "Chyba připojení k internetu.";
        } else if (
            code === 'auth/api-key-not-valid' || 
            code === 'auth/invalid-api-key' || 
            message.includes('api-key-not-valid')
        ) {
            msg = "CHYBA KONFIGURACE: Špatný API klíč ve firebaseConfig.ts.";
        } else {
            msg = "Chyba: " + message;
        }

        setError(msg);
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl max-w-sm w-full border border-gray-100">
        <div className="text-center mb-6">
          <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1" />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-gray-900">
              {isRegistering ? "Nová registrace" : "Přihlášení"}
          </h1>
          <p className="text-gray-500 text-sm mt-2">Maturitní testy SPS a STT</p>
        </div>

        {/* Přepínač Login / Registrace */}
        <div className="flex bg-gray-100 p-1 rounded-lg mb-6">
            <button
                type="button"
                onClick={() => { setIsRegistering(false); setError(''); }}
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${!isRegistering ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
                Přihlášení
            </button>
            <button
                type="button"
                onClick={() => { setIsRegistering(true); setError(''); }}
                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${isRegistering ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
                Registrace
            </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
                Uživatelské jméno
            </label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="např. Novak"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
                 Heslo {isRegistering && <span className="text-gray-400 font-normal">(min. 6 znaků)</span>}
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="******"
              required
              minLength={isRegistering ? 6 : undefined}
            />
          </div>

          {isRegistering && (
             <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                    Kód školy
                </label>
                <input
                type="text"
                value={regCode}
                onChange={(e) => setRegCode(e.target.value)}
                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                placeholder="Zadejte kód od učitele"
                required
                />
             </div>
          )}

          {error && (
            <div className="text-red-500 text-sm text-center bg-red-50 p-3 rounded-lg border border-red-100">
              <p>{error}</p>
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full text-white font-bold py-3 rounded-lg transition-colors shadow-md bg-blue-600 hover:bg-blue-700 ${loading ? 'opacity-70 cursor-wait' : ''}`}
          >
            {loading ? "Pracuji..." : (isRegistering ? "Vytvořit účet" : "Přihlásit se")}
          </button>
        </form>
      </div>
    </div>
  );
};

