import { Question } from './types';
import { RAW_SPS } from './questionsSPS';
import { RAW_STT } from './questionsSTT';

const IMAGE_KEYWORDS = ["obrázku", "náčrtu", "vidíš", "schéma", "diagram", "pozice", "kóta"];

// Seznam ID otázek pro SPS, které NEMAJÍ mít obrázek, i když obsahují klíčové slovo
const SPS_EXCLUDED_IMAGES = [211];

const parseQuestions = (raw: any[], subject: 'SPS' | 'STT'): Question[] => {
  return raw.map(item => {
    const [id, text, options, correct] = item;

    // 1. Základní kontrola klíčových slov
    let hasImage = IMAGE_KEYWORDS.some(k => text.toLowerCase().includes(k));

    // 2. Vynucení obrázků pro STT v rozsahu 91-174
    // Tyto otázky často neobsahují slovo "obrázek", ale ptají se "O jakou technologii se jedná?" a vyžadují obrázek.
    if (subject === 'STT' && id >= 91 && id <= 174) {
        hasImage = true;
    }

    // 3. Výjimky pro SPS (otázky, které obrázek mít nemají)
    if (subject === 'SPS' && SPS_EXCLUDED_IMAGES.includes(id)) {
        hasImage = false;
    }

    // Vše převádíme na malá písmena.
    // Očekáváme strukturu: /images/sps/q1.png
    const imagePath = hasImage 
        ? `/images/${subject.toLowerCase()}/q${id}.png` 
        : undefined;

    return {
      id,
      text,
      options,
      correctAnswerIndex: correct,
      imageUrl: imagePath
    };
  });
};

export const QUESTIONS_SPS: Question[] = parseQuestions(RAW_SPS, 'SPS');
export const QUESTIONS_STT: Question[] = parseQuestions(RAW_STT, 'STT');

export interface Question {
  id: number;
  text: string;
  options: string[];
  correctAnswerIndex: number; // 0-3
  imageUrl?: string;
}

export type Subject = 'SPS' | 'STT';

export enum AppMode {
  MENU = 'MENU',
  MOCK_TEST = 'MOCK_TEST',     // 1. Test nanečisto (40 questions, 30 min, hidden answers)
  TRAINING = 'TRAINING',       // 2. Náhodný trénink (Instant feedback)
  BROWSER = 'BROWSER',         // 3. Prohlížení (Search)
  MISTAKES = 'MISTAKES',       // 4. Oprava chyb
  REVIEW = 'REVIEW',           // 5. Prohlédnutí výsledků testu
  LEADERBOARD = 'LEADERBOARD', // 6. Žebříček (Novinka)
}

export interface TestResult {
  score: number;
  total: number;
  passed: boolean;
  mistakes: number[]; // IDs of wrong questions
  timeElapsed: number;
  userAnswers: Record<number, number>; // Map of QuestionID -> SelectedIndex
  questionsUsed: Question[]; // The specific list of questions used in that test run
}

// Statistiky pro jeden předmět
export interface SubjectStats {
  testsTaken: number;      // Počet dokončených testů
  totalPoints: number;     // Celkový počet získaných bodů ze všech testů
  totalMaxPoints: number;  // Celkový počet možných bodů
  bestScorePercent: number; // Nejlepší výsledek v procentech (0-100)
}

// Rozšířený uživatel o statistiky (pro načítání žebříčku)
export interface LeaderboardUser {
  displayName: string;
  statsSPS?: SubjectStats;
  statsSTT?: SubjectStats;
}

import React, { useEffect, useState } from 'react';
import { Subject, LeaderboardUser } from '../types';
import { db } from '../firebaseConfig';
import { collection, getDocs } from 'firebase/firestore';

interface Props {
  subject: Subject;
  onBack: () => void;
}

type SortType = 'SCORE' | 'GRIND';

export const Leaderboard: React.FC<Props> = ({ subject, onBack }) => {
  const [users, setUsers] = useState<LeaderboardUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [sortType, setSortType] = useState<SortType>('SCORE');

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        if (!db) return;
        const querySnapshot = await getDocs(collection(db, "users"));
        const loadedUsers: LeaderboardUser[] = [];

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          // Přidáme jen uživatele, kteří mají statistiky pro daný předmět
          if (subject === 'SPS' && data.statsSPS) {
            loadedUsers.push({ displayName: data.displayName || 'Neznámý', statsSPS: data.statsSPS });
          } else if (subject === 'STT' && data.statsSTT) {
            loadedUsers.push({ displayName: data.displayName || 'Neznámý', statsSTT: data.statsSTT });
          }
        });

        setUsers(loadedUsers);
      } catch (error) {
        console.error("Chyba při načítání žebříčku:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [subject]);

  const getStats = (user: LeaderboardUser) => {
    return subject === 'SPS' ? user.statsSPS : user.statsSTT;
  };

  const sortedUsers = [...users].sort((a, b) => {
    const statsA = getStats(a);
    const statsB = getStats(b);

    if (!statsA || !statsB) return 0;

    if (sortType === 'SCORE') {
      // 1. Nejvyšší % úspěšnost
      if (statsB.bestScorePercent !== statsA.bestScorePercent) {
        return statsB.bestScorePercent - statsA.bestScorePercent;
      }
      // 2. Při shodě rozhoduje průměrná úspěšnost
      const avgA = statsA.totalPoints / statsA.totalMaxPoints;
      const avgB = statsB.totalPoints / statsB.totalMaxPoints;
      return avgB - avgA;
    } else {
      // 1. Počet testů (Grind)
      if (statsB.testsTaken !== statsA.testsTaken) {
        return statsB.testsTaken - statsA.testsTaken;
      }
      // 2. Při shodě rozhoduje celková úspěšnost
      return statsB.bestScorePercent - statsA.bestScorePercent;
    }
  });

  const getMedalColor = (index: number) => {
    if (index === 0) return "bg-yellow-100 text-yellow-700 border-yellow-300";
    if (index === 1) return "bg-gray-100 text-gray-700 border-gray-300";
    if (index === 2) return "bg-orange-100 text-orange-800 border-orange-300";
    return "bg-white text-gray-600 border-gray-100";
  };

  return (
    <div className="max-w-4xl mx-auto p-4 min-h-screen">
      <div className="flex items-center justify-between mb-8">
        <button 
            onClick={onBack}
            className="flex items-center text-gray-500 hover:text-gray-900 transition-colors"
        >
            <svg className="w-6 h-6 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            Zpět
        </button>
        <h1 className={`text-2xl font-bold ${subject === 'SPS' ? 'text-blue-600' : 'text-orange-600'}`}>
            Žebříček {subject}
        </h1>
        <div className="w-16"></div> {/* Spacer */}
      </div>

      <div className="flex justify-center gap-2 mb-8 bg-gray-100 p-1 rounded-lg w-fit mx-auto">
          <button 
            onClick={() => setSortType('SCORE')}
            className={`px-6 py-2 rounded-md font-medium transition-all ${sortType === 'SCORE' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
          >
            Top Skóre
          </button>
          <button 
            onClick={() => setSortType('GRIND')}
            className={`px-6 py-2 rounded-md font-medium transition-all ${sortType === 'GRIND' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
          >
            Veteráni
          </button>
      </div>

      {loading ? (
        <div className="text-center py-12 text-gray-500">Načítám data...</div>
      ) : sortedUsers.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-xl shadow-sm border border-gray-200">
            <p className="text-gray-500">Zatím žádné statistiky.</p>
            <p className="text-sm text-gray-400 mt-1">Buď první, kdo dokončí test!</p>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50 text-gray-500 text-sm uppercase tracking-wider border-b border-gray-200">
                            <th className="px-6 py-4 w-20 text-center">#</th>
                            <th className="px-6 py-4">Jméno</th>
                            <th className="px-6 py-4 text-center">
                                {sortType === 'SCORE' ? 'Nejlepší %' : 'Počet testů'}
                            </th>
                            <th className="px-6 py-4 text-center">
                                {sortType === 'SCORE' ? 'Průměrná úspěšnost' : 'Nejlepší %'}
                            </th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {sortedUsers.map((user, index) => {
                            const stats = getStats(user)!;
                            const avg = Math.round((stats.totalPoints / stats.totalMaxPoints) * 100);

                            return (
                                <tr key={index} className="hover:bg-gray-50 transition-colors">
                                    <td className="px-6 py-4 text-center">
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center mx-auto font-bold border ${getMedalColor(index)}`}>
                                            {index + 1}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 font-medium text-gray-900">
                                        {user.displayName}
                                    </td>
                                    <td className="px-6 py-4 text-center font-bold text-lg text-gray-800">
                                        {sortType === 'SCORE' ? `${Math.round(stats.bestScorePercent)}%` : stats.testsTaken}
                                    </td>
                                    <td className="px-6 py-4 text-center text-gray-500">
                                        {sortType === 'SCORE' ? `${avg}%` : `${Math.round(stats.bestScorePercent)}%`}
                                    </td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Question, AppMode, TestResult } from '../types';
import { QuestionCard } from './QuestionCard';
import { db, auth } from '../firebaseConfig';
import { doc, getDoc, setDoc } from 'firebase/firestore';

interface Props {
  mode: AppMode;
  mistakeIds?: number[]; // IDs for "Oprava chyb" mode
  onComplete: (result: TestResult) => void;
  onExit: () => void;

  // The full dataset for the current subject
  initialQuestionsForMode: Question[];

  // New props for Review Mode
  initialQuestions?: Question[];
  initialAnswers?: Record<number, number>;
  subject?: 'SPS' | 'STT'; // Potřebujeme vědět předmět pro ukládání statistik
}

export const TestRunner: React.FC<Props> = ({ mode, mistakeIds, onComplete, onExit, initialQuestionsForMode, initialQuestions, initialAnswers, subject }) => {
  const [currentQuestions, setCurrentQuestions] = useState<Question[]>([]);
  const [answers, setAnswers] = useState<Record<number, number>>({}); // qId -> selectedIndex
  const [timeLeft, setTimeLeft] = useState(30 * 60); // 30 mins in seconds
  const [currentIndex, setCurrentIndex] = useState(0);

  // Initialize Test
  useEffect(() => {
    let q: Question[] = [];

    if (initialQuestions && mode === AppMode.REVIEW) {
        q = initialQuestions;
        if (initialAnswers) {
            setAnswers(initialAnswers);
        }
    } else if (mode === AppMode.MOCK_TEST) {
      // Shuffle and pick 40
      const shuffled = [...initialQuestionsForMode].sort(() => 0.5 - Math.random());
      q = shuffled.slice(0, 40);
    } else if (mode === AppMode.MISTAKES && mistakeIds) {
      q = initialQuestionsForMode.filter(q => mistakeIds.includes(q.id));
    } else if (mode === AppMode.TRAINING) {
      // Random training
      q = [...initialQuestionsForMode].sort(() => 0.5 - Math.random());
    } else {
        q = [...initialQuestionsForMode];
    }
    setCurrentQuestions(q);
  }, [mode, mistakeIds, initialQuestions, initialAnswers, initialQuestionsForMode]);

  // Timer Logic (Only for Mock Test)
  useEffect(() => {
    if (mode !== AppMode.MOCK_TEST) return;

    const timer = setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 1) {
          clearInterval(timer);
          finishTest();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [mode]); // eslint-disable-next-line react-hooks/exhaustive-deps

  const handleAnswer = (qId: number, idx: number, isCorrect: boolean) => {
    setAnswers(prev => ({ ...prev, [qId]: idx }));
  };

  const saveStats = async (score: number, total: number) => {
      // Statistiky ukládáme pouze pro kompletní testy (MOCK_TEST) nebo trénink,
      // ale pro žebříček je nejspravedlivější počítat hlavně MOCK_TEST nebo větší sady.
      // Pro jednoduchost budeme zatím počítat MOCK_TEST, kde je skóre relevantní.
      if (mode !== AppMode.MOCK_TEST || !subject || !auth.currentUser) return;

      try {
          const userRef = doc(db, "users", auth.currentUser.uid);
          const userSnap = await getDoc(userRef);

          if (userSnap.exists()) {
              const data = userSnap.data();
              const fieldName = subject === 'SPS' ? 'statsSPS' : 'statsSTT';
              const currentStats = data[fieldName] || {
                  testsTaken: 0,
                  totalPoints: 0,
                  totalMaxPoints: 0,
                  bestScorePercent: 0
              };

              const currentPercent = (score / total) * 100;

              const newStats = {
                  testsTaken: currentStats.testsTaken + 1,
                  totalPoints: currentStats.totalPoints + score,
                  totalMaxPoints: currentStats.totalMaxPoints + total,
                  bestScorePercent: Math.max(currentStats.bestScorePercent, currentPercent)
              };

              await setDoc(userRef, { [fieldName]: newStats }, { merge: true });
          }
      } catch (e) {
          console.error("Chyba při ukládání statistik:", e);
      }
  };

  const finishTest = async () => {
    let score = 0;
    const mistakes: number[] = [];

    currentQuestions.forEach(q => {
      if (answers[q.id] === q.correctAnswerIndex) {
        score++;
      } else {
        mistakes.push(q.id);
      }
    });

    // 44% threshold
    const total = currentQuestions.length;
    const percentage = total === 0 ? 0 : (score / total) * 100;
    const passed = percentage >= 44;

    // Uložit statistiky do DB (nečekáme na dokončení)
    saveStats(score, total);

    onComplete({
      score,
      total,
      passed,
      mistakes,
      timeElapsed: (30 * 60) - timeLeft,
      userAnswers: answers,
      questionsUsed: currentQuestions
    });
  };

  if (currentQuestions.length === 0) {
    return (
        <div className="text-center p-12">
            <h2 className="text-xl font-bold text-gray-700">Žádné otázky k zobrazení.</h2>
            <p className="text-gray-500 mb-4">V tomto režimu nejsou dostupné žádné otázky.</p>
            <button onClick={onExit} className="text-blue-600 underline">Zpět do menu</button>
        </div>
    );
  }

  // Formatting time
  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const currentQ = currentQuestions[currentIndex];

  return (
    <div className="max-w-4xl mx-auto w-full">
      {/* Header Bar */}
      <div className="bg-white sticky top-0 z-10 shadow-sm border-b border-gray-200 px-6 py-4 mb-6 flex justify-between items-center rounded-b-xl">
        <div className="flex items-center gap-4">
            <button onClick={onExit} className="text-gray-500 hover:text-gray-900 transition-colors">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            </button>
            <div>
                <h2 className="font-bold text-gray-800">
                    {mode === AppMode.MOCK_TEST ? 'Test nanečisto' : 
                     mode === AppMode.TRAINING ? 'Náhodný trénink' : 
                     mode === AppMode.MISTAKES ? 'Oprava chyb' : 
                     mode === AppMode.REVIEW ? 'Kontrola testu' : 'Test'}
                </h2>
                <div className="text-sm text-gray-500">
                    Otázka {currentIndex + 1} z {currentQuestions.length}
                </div>
            </div>
        </div>

        {mode === AppMode.MOCK_TEST && (
            <div className={`font-mono text-xl font-bold ${timeLeft < 300 ? 'text-red-600' : 'text-blue-600'}`}>
                {formatTime(timeLeft)}
            </div>
        )}
      </div>

      <div className="px-4">
          <QuestionCard 
            question={currentQ}
            mode={mode}
            onAnswer={handleAnswer}
            showFeedback={mode !== AppMode.MOCK_TEST} // Show feedback in Review/Training/Mistakes
            userAnswer={answers[currentQ.id]}
          />
      </div>

      {/* Footer Navigation */}
      <div className="flex justify-between items-center px-6 py-8">
        <button 
            onClick={() => setCurrentIndex(p => Math.max(0, p - 1))}
            disabled={currentIndex === 0}
            className="px-6 py-2 rounded-lg bg-gray-100 text-gray-700 font-medium disabled:opacity-50 hover:bg-gray-200 transition-colors"
        >
            Předchozí
        </button>

        {mode === AppMode.TRAINING || mode === AppMode.MISTAKES ? (
             <button 
             onClick={() => {
                 if (currentIndex === currentQuestions.length - 1) {
                     finishTest();
                 } else {
                    setCurrentIndex(p => p + 1);
                 }
             }}
             className="px-6 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
         >
             {currentIndex === currentQuestions.length - 1 ? 'Ukončit trénink' : 'Další otázka'}
         </button>
        ) : (
            currentIndex === currentQuestions.length - 1 ? (
                <button 
                    onClick={mode === AppMode.REVIEW ? onExit : finishTest}
                    className="px-8 py-2 rounded-lg bg-green-600 text-white font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-200"
                >
                    {mode === AppMode.REVIEW ? 'Zpět do menu' : 'Vyhodnotit test'}
                </button>
            ) : (
                <button 
                    onClick={() => setCurrentIndex(p => Math.min(currentQuestions.length - 1, p + 1))}
                    className="px-6 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
                >
                    Další
                </button>
            )
        )}
      </div>
    </div>
  );
};

export interface Question {
  id: number;
  text: string;
  options: string[];
  correctAnswerIndex: number; // 0-3
  imageUrl?: string;
}

export type Subject = 'SPS' | 'STT';

export enum AppMode {
  MENU = 'MENU',
  MOCK_TEST = 'MOCK_TEST',     // 1. Test nanečisto (40 questions, 30 min, hidden answers)
  TRAINING = 'TRAINING',       // 2. Náhodný trénink (Instant feedback)
  BROWSER = 'BROWSER',         // 3. Prohlížení (Search)
  MISTAKES = 'MISTAKES',       // 4. Oprava chyb
  REVIEW = 'REVIEW',           // 5. Prohlédnutí výsledků testu
  LEADERBOARD = 'LEADERBOARD', // 6. Žebříček (Novinka)
}

export interface TestResult {
  score: number;
  total: number;
  passed: boolean;
  mistakes: number[]; // IDs of wrong questions
  timeElapsed: number;
  userAnswers: Record<number, number>; // Map of QuestionID -> SelectedIndex
  questionsUsed: Question[]; // The specific list of questions used in that test run
}

// Statistiky pro jeden předmět
export interface SubjectStats {
  testsTaken: number;      // Počet dokončených testů
  totalPoints: number;     // Celkový počet získaných bodů ze všech testů
  totalMaxPoints: number;  // Celkový počet možných bodů
  bestScorePercent: number; // Nejlepší výsledek v procentech (0-100)
}

// Rozšířený uživatel o statistiky (pro načítání žebříčku)
export interface LeaderboardUser {
  displayName: string;
  statsSPS?: SubjectStats;
  statsSTT?: SubjectStats;
}

import React, { useEffect, useState } from 'react';
import { Subject, LeaderboardUser } from '../types';
import { db } from '../firebaseConfig';
import { collection, getDocs } from 'firebase/firestore';

interface Props {
  subject: Subject;
  onBack: () => void;
}

type SortType = 'SCORE' | 'GRIND';

export const Leaderboard: React.FC<Props> = ({ subject, onBack }) => {
  const [users, setUsers] = useState<LeaderboardUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [sortType, setSortType] = useState<SortType>('SCORE');

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        if (!db) return;
        const querySnapshot = await getDocs(collection(db, "users"));
        const loadedUsers: LeaderboardUser[] = [];

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          // Přidáme jen uživatele, kteří mají statistiky pro daný předmět
          if (subject === 'SPS' && data.statsSPS) {
            loadedUsers.push({ displayName: data.displayName || 'Neznámý', statsSPS: data.statsSPS });
          } else if (subject === 'STT' && data.statsSTT) {
            loadedUsers.push({ displayName: data.displayName || 'Neznámý', statsSTT: data.statsSTT });
          }
        });

        setUsers(loadedUsers);
      } catch (error) {
        console.error("Chyba při načítání žebříčku:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [subject]);

  const getStats = (user: LeaderboardUser) => {
    return subject === 'SPS' ? user.statsSPS : user.statsSTT;
  };

  const sortedUsers = [...users].sort((a, b) => {
    const statsA = getStats(a);
    const statsB = getStats(b);

    if (!statsA || !statsB) return 0;

    if (sortType === 'SCORE') {
      // 1. Nejvyšší % úspěšnost
      if (statsB.bestScorePercent !== statsA.bestScorePercent) {
        return statsB.bestScorePercent - statsA.bestScorePercent;
      }
      // 2. Při shodě rozhoduje průměrná úspěšnost
      const avgA = statsA.totalPoints / statsA.totalMaxPoints;
      const avgB = statsB.totalPoints / statsB.totalMaxPoints;
      return avgB - avgA;
    } else {
      // 1. Počet testů (Grind)
      if (statsB.testsTaken !== statsA.testsTaken) {
        return statsB.testsTaken - statsA.testsTaken;
      }
      // 2. Při shodě rozhoduje celková úspěšnost
      return statsB.bestScorePercent - statsA.bestScorePercent;
    }
  });

  const getMedalColor = (index: number) => {
    if (index === 0) return "bg-yellow-100 text-yellow-700 border-yellow-300";
    if (index === 1) return "bg-gray-100 text-gray-700 border-gray-300";
    if (index === 2) return "bg-orange-100 text-orange-800 border-orange-300";
    return "bg-white text-gray-600 border-gray-100";
  };

  return (
    <div className="max-w-4xl mx-auto p-4 min-h-screen">
      <div className="flex items-center justify-between mb-8">
        <button 
            onClick={onBack}
            className="flex items-center text-gray-500 hover:text-gray-900 transition-colors"
        >
            <svg className="w-6 h-6 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            Zpět
        </button>
        <h1 className={`text-2xl font-bold ${subject === 'SPS' ? 'text-blue-600' : 'text-orange-600'}`}>
            Žebříček {subject}
        </h1>
        <div className="w-16"></div> {/* Spacer */}
      </div>

      <div className="flex justify-center gap-2 mb-8 bg-gray-100 p-1 rounded-lg w-fit mx-auto">
          <button 
            onClick={() => setSortType('SCORE')}
            className={`px-6 py-2 rounded-md font-medium transition-all ${sortType === 'SCORE' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
          >
            Top Skóre
          </button>
          <button 
            onClick={() => setSortType('GRIND')}
            className={`px-6 py-2 rounded-md font-medium transition-all ${sortType === 'GRIND' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
          >
            Veteráni
          </button>
      </div>

      {loading ? (
        <div className="text-center py-12 text-gray-500">Načítám data...</div>
      ) : sortedUsers.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-xl shadow-sm border border-gray-200">
            <p className="text-gray-500">Zatím žádné statistiky.</p>
            <p className="text-sm text-gray-400 mt-1">Buď první, kdo dokončí test!</p>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50 text-gray-500 text-sm uppercase tracking-wider border-b border-gray-200">
                            <th className="px-6 py-4 w-20 text-center">#</th>
                            <th className="px-6 py-4">Jméno</th>
                            <th className="px-6 py-4 text-center">
                                {sortType === 'SCORE' ? 'Nejlepší %' : 'Počet testů'}
                            </th>
                            <th className="px-6 py-4 text-center">
                                {sortType === 'SCORE' ? 'Průměrná úspěšnost' : 'Nejlepší %'}
                            </th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {sortedUsers.map((user, index) => {
                            const stats = getStats(user)!;
                            const avg = Math.round((stats.totalPoints / stats.totalMaxPoints) * 100);

                            return (
                                <tr key={index} className="hover:bg-gray-50 transition-colors">
                                    <td className="px-6 py-4 text-center">
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center mx-auto font-bold border ${getMedalColor(index)}`}>
                                            {index + 1}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 font-medium text-gray-900">
                                        {user.displayName}
                                    </td>
                                    <td className="px-6 py-4 text-center font-bold text-lg text-gray-800">
                                        {sortType === 'SCORE' ? `${Math.round(stats.bestScorePercent)}%` : stats.testsTaken}
                                    </td>
                                    <td className="px-6 py-4 text-center text-gray-500">
                                        {sortType === 'SCORE' ? `${avg}%` : `${Math.round(stats.bestScorePercent)}%`}
                                    </td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
      )}
    </div>
  );
};

