import React, { useState } from 'react';
import { AppUser } from '../users';
import { auth } from '../firebaseConfig';
import { signInWithEmailAndPassword } from 'firebase/auth';

interface Props {
  onLogin: (user: AppUser) => void;
}

export const LoginScreen: React.FC<Props> = ({ onLogin }) => {
  const [input, setInput] = useState(''); 
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Funkce pro zpracování vstupu (buď celé jméno nebo generování domény)
  const processEmail = (userInput: string) => {
      const trimmedInput = userInput.trim();

      // 1. Pokud uživatel zadal celý email (obsahuje @), použijeme ho tak, jak je.
      // To umožní přihlášení přes gmail.com nebo jiné domény pro adminy/učitele.
      if (trimmedInput.includes('@')) {
          return trimmedInput;
      }

      // 2. Pokud uživatel zadal jen jméno (pro studenty), vygenerujeme @maturita.app
      let cleanName = trimmedInput.toLowerCase();

      // Odstraníme diakritiku a mezery
      cleanName = cleanName.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, '');

      return `${cleanName}@maturita.app`;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!auth) {
        setError("Chyba: Firebase není nakonfigurován.");
        setLoading(false);
        return;
    }

    try {
        // Zpracování emailu
        const emailToUse = processEmail(input);
        console.log("Pokus o přihlášení jako:", emailToUse);

        // PŘIHLÁŠENÍ
        const userCredential = await signInWithEmailAndPassword(auth, emailToUse, password);

        onLogin({
            uid: userCredential.user.uid,
            email: emailToUse,
            displayName: userCredential.user.displayName || input
        });

    } catch (err: any) {
        console.error("Login Error:", err);

        let msg = "Nastala neznámá chyba.";
        const code = err.code;
        const message = err.message || "";

        if (code === 'auth/invalid-credential' || code === 'auth/wrong-password') {
            msg = "Nesprávné jméno nebo heslo.";
        } else if (code === 'auth/user-not-found' || code === 'auth/invalid-email') {
            msg = "Tento uživatel neexistuje.";
        } else if (code === 'auth/too-many-requests') {
            msg = "Příliš mnoho nezdařených pokusů. Zkuste to prosím později.";
        } else if (code === 'auth/network-request-failed') {
            msg = "Chyba připojení k internetu.";
        } else if (
            code === 'auth/api-key-not-valid' || 
            code === 'auth/invalid-api-key'
        ) {
            msg = "CHYBA KONFIGURACE: Špatný API klíč.";
        } else {
            msg = "Chyba: " + message;
        }

        setError(msg);
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl max-w-sm w-full border border-gray-100">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1" />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-gray-900">
              Přihlášení
          </h1>
          <p className="text-gray-500 text-sm mt-2">Maturitní testy SPS a STT</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
                Uživatelské jméno nebo Email
            </label>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              autoFocus
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
                 Heslo
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
            />
          </div>

          {error && (
            <div className="text-red-500 text-sm text-center bg-red-50 p-3 rounded-lg border border-red-100">
              <p>{error}</p>
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full text-white font-bold py-3 rounded-lg transition-colors shadow-md bg-blue-600 hover:bg-blue-700 ${loading ? 'opacity-70 cursor-wait' : ''}`}
          >
            {loading ? "Ověřuji..." : "Přihlásit se"}
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Question, AppMode } from '../types';

interface Props {
  question: Question;
  mode: AppMode;
  onAnswer: (questionId: number, selectedIndex: number, isCorrect: boolean) => void;
  showFeedback: boolean;
  userAnswer?: number | null;
}

export const QuestionCard: React.FC<Props> = ({
  question,
  mode,
  onAnswer,
  showFeedback,
  userAnswer
}) => {
  const [selected, setSelected] = useState<number | null>(userAnswer ?? null);
  const [imgError, setImgError] = useState(false);
  const [currentImgSrc, setCurrentImgSrc] = useState<string | undefined>(question.imageUrl);

  useEffect(() => {
    setSelected(userAnswer ?? null);
    setImgError(false);
    // Resetujeme zdroj obrázku na výchozí hodnotu (což je obvykle .png z constants.ts)
    setCurrentImgSrc(question.imageUrl);
  }, [question, userAnswer]);

  const handleSelect = (index: number) => {
    if (showFeedback && selected !== null) return;
    if (mode === AppMode.REVIEW) return;

    setSelected(index);
    const isCorrect = index === question.correctAnswerIndex;
    onAnswer(question.id, index, isCorrect);
  };

  const handleImageError = () => {
      // Pokud se nepodařilo načíst obrázek a končí na .png, zkusíme .jpg
      if (currentImgSrc && currentImgSrc.endsWith('.png')) {
          setCurrentImgSrc(currentImgSrc.replace('.png', '.jpg'));
      } else {
          // Pokud už to není .png (nebo už jsme zkusili .jpg), tak je to finální chyba
          setImgError(true);
      }
  };

  // --- PARSER MATEMATICKÝCH VZORCŮ ---
  const renderMathText = (text: string) => {
    // Pokud text neobsahuje naše klíčové značky, vrátíme ho jako obyčejný string (pro výkon)
    if (!text.includes('sqrt') && !text.includes('_') && !text.includes('^')) {
        return text;
    }

    let html = text;

    // 1. Odmocnina: sqrt(vnitrek) -> <span class="math-root">...</span>
    // Používáme regex, který najde "sqrt(" a koncovou ")". Pozor, neumí vnořené závorky, ale pro vzorce v testu stačí.
    html = html.replace(/sqrt\((.*?)\)/g, '<span class="math-root"><span class="math-radical">√</span><span class="math-vinculum">$1</span></span>');

    // 2. Dolní index: M_RED -> M<sub>RED</sub> (chytá písmeno/číslo před podtržítkem a slovo za ním)
    // Např. M_RED, M_O, M_K
    html = html.replace(/([a-zA-Z0-9])_([a-zA-Z0-9]+)/g, '$1<sub>$2</sub>');

    // 3. Horní index (mocnina): ^2 -> <sup>2</sup>
    html = html.replace(/\^([0-9]+)/g, '<sup>$1</sup>');

    // Vrátíme jako React element s použitím patkového písma pro "profesionální" vzhled vzorců
    return <span className="font-serif text-lg tracking-wide" dangerouslySetInnerHTML={{ __html: html }} />;
  };

  const getOptionClass = (index: number) => {
    const base = "w-full p-4 text-left border rounded-lg transition-all duration-200 flex items-center gap-3 ";

    if (mode === AppMode.MOCK_TEST) {
      return base + (selected === index 
        ? "border-blue-500 bg-blue-50 text-blue-900 ring-2 ring-blue-200" 
        : "border-gray-200 hover:bg-gray-50 text-gray-700");
    }

    if (showFeedback || mode === AppMode.TRAINING || mode === AppMode.MISTAKES || mode === AppMode.REVIEW) {
        if (selected === null && mode !== AppMode.REVIEW) return base + "border-gray-200 hover:bg-gray-50 text-gray-700";

        if (index === question.correctAnswerIndex) {
            return base + "border-green-500 bg-green-50 text-green-900 ring-2 ring-green-200 font-medium";
        }
        if (selected === index && index !== question.correctAnswerIndex) {
            return base + "border-red-500 bg-red-50 text-red-900 ring-2 ring-red-200";
        }
        return base + "border-gray-200 opacity-60";
    }

    return base + "border-gray-200";
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 max-w-3xl mx-auto mb-6">
      <div className="flex justify-between items-start mb-4">
        <h3 className="text-lg font-semibold text-gray-900 leading-relaxed">
          <span className="text-blue-600 mr-2">#{question.id}</span>
          {/* Použijeme parser i pro nadpis otázky */}
          {renderMathText(question.text)}
        </h3>
      </div>

      {question.imageUrl && !imgError && currentImgSrc && (
        <div className="mb-6 rounded-lg overflow-hidden border border-gray-200 bg-gray-50 min-h-[200px] flex items-center justify-center relative">
          <img 
            src={currentImgSrc} 
            alt="Ilustrace k otázce" 
            className="w-full h-auto max-h-80 object-contain mx-auto"
            onError={handleImageError}
            loading="lazy"
          />
        </div>
      )}

      {question.imageUrl && imgError && (
          <div className="mb-6 p-4 text-center text-sm text-red-400 italic bg-red-50 rounded-lg border border-red-100">
             Obrázek se nepodařilo načíst: {question.imageUrl} (ani .jpg varianta)
          </div>
      )}

      <div className="space-y-3">
        {question.options.map((opt, idx) => (
          <button
            key={idx}
            onClick={() => handleSelect(idx)}
            disabled={((mode === AppMode.TRAINING || mode === AppMode.MISTAKES) && selected !== null) || mode === AppMode.REVIEW}
            className={getOptionClass(idx)}
          >
            <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center flex-shrink-0 
                ${selected === idx ? 'border-current' : 'border-gray-300'}`}>
                {selected === idx && <div className="w-2.5 h-2.5 rounded-full bg-current" />}
            </div>
            {/* Použijeme parser pro možnosti odpovědí */}
            <span>{renderMathText(opt)}</span>
          </button>
        ))}
      </div>
    </div>
  );
};

