      const trimmedInput = userInput.trim();

      // 1. Pokud uživatel zadal celý email (obsahuje @), použijeme ho tak, jak je.
      // To umožní přihlášení přes gmail.com nebo jiné domény pro adminy/učitele.
      if (trimmedInput.includes('@')) {
          return trimmedInput;
      }

      // 2. Pokud uživatel zadal jen jméno (pro studenty), vygenerujeme @maturita.app
      let cleanName = trimmedInput.toLowerCase();

      // Odstraníme diakritiku a mezery
      cleanName = cleanName.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, '');

      return `${cleanName}@maturita.app`;
  };

  const getErrorMessage = (err: any) => {
      const code = err.code;
      const message = err.message || "";

      if (code === 'auth/invalid-credential' || code === 'auth/wrong-password') {
          return "Nesprávné jméno nebo heslo.";
      } else if (code === 'auth/user-not-found' || code === 'auth/invalid-email') {
          return "Tento uživatel neexistuje.";
      } else if (code === 'auth/email-already-in-use') {
          return "Uživatel s tímto jménem již existuje. Zadejte správné heslo.";
      } else if (code === 'auth/weak-password') {
          return "Heslo je příliš slabé (musí mít alespoň 6 znaků).";
      } else if (code === 'auth/too-many-requests') {
          return "Příliš mnoho nezdařených pokusů. Zkuste to prosím později.";
      } else if (code === 'auth/network-request-failed') {
          return "Chyba připojení k internetu.";
      } else if (
          code === 'auth/api-key-not-valid' || 
          code === 'auth/invalid-api-key'
      ) {
          return "CHYBA KONFIGURACE: Špatný API klíč.";
      } else {
          return "Chyba: " + message;
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!auth) {
        setError("Chyba: Firebase není nakonfigurován.");
        setLoading(false);
        return;
    }

    const emailToUse = processEmail(input);
    console.log("Pokus o přihlášení jako:", emailToUse);

    try {
        // 1. Pokus o PŘIHLÁŠENÍ
        const userCredential = await signInWithEmailAndPassword(auth, emailToUse, password);

        onLogin({
            uid: userCredential.user.uid,
            email: emailToUse,
            displayName: userCredential.user.displayName || input
        });

    } catch (loginErr: any) {
        // Pokud přihlášení selže s chybou, která může znamenat "uživatel neexistuje", zkusíme registraci.
        // Poznámka: auth/invalid-credential v novém API často skrývá user-not-found.
        const code = loginErr.code;

        if (code === 'auth/user-not-found' || code === 'auth/invalid-credential' || code === 'auth/wrong-password') {
            try {
                console.log("Přihlášení selhalo, zkouším registraci...");
                // 2. Pokus o REGISTRACI
                const newUserCredential = await createUserWithEmailAndPassword(auth, emailToUse, password);

                // Nastavení zobrazovaného jména
                await updateProfile(newUserCredential.user, {
                    displayName: input
                });

                onLogin({
                    uid: newUserCredential.user.uid,
                    email: emailToUse,
                    displayName: input
                });
            } catch (createErr: any) {
                // Pokud selže i registrace
                console.error("Registration Error:", createErr);

                // Pokud chyba registrace je "email already in use", znamená to, že původní login chyba byla "špatné heslo"
                if (createErr.code === 'auth/email-already-in-use') {
                    setError("Nesprávné heslo.");
                } else {
                    // Jinak zobrazíme chybu registrace (např. slabé heslo)
                    setError(getErrorMessage(createErr));
                }
            }
        } else {
            // Jiná chyba při loginu (síť, blokace atd.)
            console.error("Login Error:", loginErr);
            setError(getErrorMessage(loginErr));
        }
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl max-w-sm w-full border border-gray-100">
